// Code node: "Fetch GitHub Activity" (Run Once for All Items)
// Uses the public GitHub REST API without a token (60 requests/hour limit — this uses 4-6 per run).
const USER = 'aqibrehman325';
const WATCH = ['n8n-io/n8n']; // public repos to follow (releases + latest commits)
const MAX_AGE_MIN = 30; // webhook path: reuse cached digest if younger than this

const store = $getWorkflowStaticData('global');
const first = $input.first().json || {};
const fromWebhook = !!first.headers;
const ageMin = store.digest ? (Date.now() - Date.parse(store.digest.fetchedAt)) / 60000 : Infinity;
// Manual refresh is throttled to once every 2 minutes to protect the API rate limit
const force = !fromWebhook || (first.query && first.query.refresh === '1' && ageMin > 2);

if (!force && ageMin < MAX_AGE_MIN) {
  return [{ json: { cached: true } }];
}

const gh = async (path) => {
  try {
    return await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.github.com' + path,
      headers: { 'User-Agent': 'n8n-github-digest', Accept: 'application/vnd.github+json' },
      json: true,
      timeout: 15000,
    });
  } catch (e) {
    return { __error: String((e && (e.message || e.code)) || 'request failed').slice(0, 160) };
  }
};

const since24 = Date.now() - 24 * 3600e3;
const since7d = Date.now() - 7 * 24 * 3600e3;
const errors = [];

const reposRaw = await gh(`/users/${USER}/repos?sort=pushed&per_page=12`);
const repos = Array.isArray(reposRaw)
  ? reposRaw.map((r) => ({
      name: r.name,
      url: r.html_url,
      description: r.description || '',
      language: r.language || '—',
      stars: r.stargazers_count,
      forks: r.forks_count,
      openIssues: r.open_issues_count,
      pushedAt: r.pushed_at,
    }))
  : (errors.push('repos: ' + (reposRaw.__error || 'unexpected response')), []);

const eventsRaw = await gh(`/users/${USER}/events/public?per_page=100`);
const events = Array.isArray(eventsRaw) ? eventsRaw : (errors.push('events: ' + (eventsRaw.__error || 'unexpected response')), []);
const summarize = (since) => {
  const ev = events.filter((e) => Date.parse(e.created_at) >= since);
  return {
    events: ev.length,
    pushes: ev.filter((e) => e.type === 'PushEvent').length,
    commits: ev.filter((e) => e.type === 'PushEvent').reduce((s, e) => s + ((e.payload && (e.payload.size || (e.payload.commits || []).length)) || 0), 0),
    pullRequests: ev.filter((e) => e.type === 'PullRequestEvent').length,
    issues: ev.filter((e) => e.type === 'IssuesEvent' || e.type === 'IssueCommentEvent').length,
    newRepos: ev.filter((e) => e.type === 'CreateEvent' && e.payload && e.payload.ref_type === 'repository').length,
  };
};
const recent = events.slice(0, 15).map((e) => ({
  type: e.type.replace(/Event$/, ''),
  repo: e.repo && e.repo.name,
  at: e.created_at,
  detail:
    e.type === 'PushEvent'
      ? `${(e.payload && (e.payload.size || (e.payload.commits || []).length)) || 0} commit(s) to ${String((e.payload && e.payload.ref) || '').replace('refs/heads/', '')}`
      : e.type === 'PullRequestEvent'
      ? `${e.payload.action} PR #${e.payload.number}`
      : e.type === 'CreateEvent'
      ? `created ${e.payload.ref_type}${e.payload.ref ? ' ' + e.payload.ref : ''}`
      : e.payload && e.payload.action ? e.payload.action : '',
}));

const watch = [];
for (const full of WATCH) {
  const rel = await gh(`/repos/${full}/releases?per_page=3`);
  const com = await gh(`/repos/${full}/commits?per_page=5`);
  if (!Array.isArray(rel)) errors.push(`${full} releases: ${rel.__error || 'unexpected response'}`);
  if (!Array.isArray(com)) errors.push(`${full} commits: ${com.__error || 'unexpected response'}`);
  watch.push({
    repo: full,
    url: `https://github.com/${full}`,
    releases: Array.isArray(rel) ? rel.map((r) => ({ name: r.name || r.tag_name, url: r.html_url, at: r.published_at })) : [],
    commits: Array.isArray(com)
      ? com.map((c) => ({ sha: c.sha.slice(0, 7), url: c.html_url, message: String(c.commit.message).split('\n')[0].slice(0, 110), author: (c.commit.author && c.commit.author.name) || '', at: c.commit.author && c.commit.author.date }))
      : [],
  });
}

const digest = {
  user: USER,
  fetchedAt: new Date().toISOString(),
  last24h: summarize(since24),
  last7d: summarize(since7d),
  repos,
  recent,
  watch,
  errors,
};
store.digest = digest;
store.history = [{ at: digest.fetchedAt, ...digest.last24h }, ...(store.history || [])].slice(0, 30);
return [{ json: { cached: false, errors: errors.length, repos: repos.length, events: events.length } }];

