// Code node: "Build Digest Page" (Run Once for All Items)
const store = $getWorkflowStaticData('global');
const d = store.digest;
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const ago = (iso) => {
  if (!iso) return '—';
  const m = Math.round((Date.now() - Date.parse(iso)) / 60000);
  if (m < 60) return `${m} min ago`;
  const h = Math.round(m / 60);
  if (h < 48) return `${h} h ago`;
  return `${Math.round(h / 24)} days ago`;
};

let body;
if (!d) {
  body = '<div class="card empty">No digest yet. It is generated daily at 09:00 PKT, or add <code>?refresh=1</code> to this URL.</div>';
} else {
  const stat = (label, v) => `<div class="kpi"><span class="muted">${label}</span><b>${v}</b></div>`;
  const repoRows = d.repos
    .map((r) => `<tr><td><a href="${esc(r.url)}">${esc(r.name)}</a><br><span class="muted">${esc(r.description)}</span></td><td>${esc(r.language)}</td><td>★ ${r.stars} · ⑂ ${r.forks}</td><td>${r.openIssues}</td><td>${esc(ago(r.pushedAt))}</td></tr>`)
    .join('');
  const recent = d.recent.map((e) => `<li><span class="pill">${esc(e.type)}</span> <strong>${esc(e.repo)}</strong> — ${esc(e.detail)} <span class="muted">· ${esc(ago(e.at))}</span></li>`).join('');
  const watch = d.watch
    .map(
      (w) => `<section class="card pad"><h3><a href="${esc(w.url)}">${esc(w.repo)}</a></h3>
<div class="cols"><div><h4>Latest releases</h4><ul class="plain">${w.releases.map((r) => `<li><a href="${esc(r.url)}">${esc(r.name)}</a> <span class="muted">· ${esc(ago(r.at))}</span></li>`).join('') || '<li class="muted">None</li>'}</ul></div>
<div><h4>Latest commits</h4><ul class="plain">${w.commits.map((c) => `<li><a href="${esc(c.url)}"><code>${esc(c.sha)}</code></a> ${esc(c.message)} <span class="muted">· ${esc(c.author)}, ${esc(ago(c.at))}</span></li>`).join('') || '<li class="muted">None</li>'}</ul></div></div></section>`
    )
    .join('');
  body = `
<section class="kpis">
${stat('Events (24h)', d.last24h.events)}${stat('Commits (24h)', d.last24h.commits)}${stat('Commits (7 days)', d.last7d.commits)}
${stat('Pull requests (7 days)', d.last7d.pullRequests)}${stat('Issues & comments (7 days)', d.last7d.issues)}${stat('Public repos tracked', d.repos.length)}
</section>
<h2>Repositories — ${esc(d.user)}</h2>
<div class="card"><table><thead><tr><th>Repository</th><th>Language</th><th>Stars / forks</th><th>Open issues</th><th>Last push</th></tr></thead><tbody>${repoRows || '<tr><td colspan="5" class="muted">No public repositories.</td></tr>'}</tbody></table></div>
<h2>Recent activity</h2>
${recent ? `<ul class="card list">${recent}</ul>` : '<div class="card empty">No public activity in the last 90 days.</div>'}
<h2>Watched projects</h2>
${watch}
${d.errors.length ? `<p class="warn">Some data could not be loaded: ${esc(d.errors.join('; '))}</p>` : ''}`;
}

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>GitHub Activity Digest</title>
<style>
:root{--bg:#f6f7f9;--card:#fff;--ink:#16181d;--muted:#6b7280;--line:#e5e7eb;--accent:#4f46e5;--warn:#d97706}
@media (prefers-color-scheme:dark){:root{--bg:#0f1115;--card:#171a21;--ink:#e8eaed;--muted:#9aa1ad;--line:#2a2f3a;--accent:#8b8cf8}}
*{box-sizing:border-box}body{margin:0;font:14px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--ink)}
main{max-width:1050px;margin:0 auto;padding:24px 16px}h1{font-size:22px;margin:0 0 4px}h2{font-size:16px;margin:24px 0 10px}h3{margin:0 0 8px;font-size:15px}h4{margin:0 0 6px;font-size:13px;color:var(--muted)}
a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:18px 0}
.kpi{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px}.kpi b{display:block;font-size:22px}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;overflow-x:auto}.pad{padding:16px;margin-bottom:12px}
table{width:100%;border-collapse:collapse;min-width:640px}th,td{padding:10px 12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
th{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}.muted{color:var(--muted);font-size:12px}
.list{list-style:none;padding:8px 14px;margin:0}.list li{padding:6px 0;border-bottom:1px solid var(--line)}.list li:last-child{border:0}
.plain{list-style:none;padding:0;margin:0}.plain li{margin:4px 0}.cols{display:grid;grid-template-columns:1fr 2fr;gap:16px}@media(max-width:700px){.cols{grid-template-columns:1fr}}
.pill{display:inline-block;font-size:11px;font-weight:600;padding:1px 7px;border-radius:999px;background:var(--accent);color:#fff}
.empty{padding:24px;text-align:center;color:var(--muted)}.warn{color:var(--warn)}code{font-size:12px}
</style></head><body><main>
<h1>GitHub Activity Digest</h1>
<div class="muted">${d ? `Updated ${esc(ago(d.fetchedAt))} · refreshes daily at 09:00 PKT` : ''} · <a href="?refresh=1">Refresh now</a></div>
${body}
</main></body></html>`;
return [{ json: { html } }];
